// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 200,
  "IDEA_BATCH_SIZE": 25,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// Central prompt library. Every OpenAI agent used by this workflow lives
// here so prompts are versioned with the workflow itself and can be
// diffed in git (mirrored in prompts/*.md).
const PROMPT_VERSION = $('Factory Config').first().json.cfg.PROMPT_VERSION || 'v1.0.0';
const PROMPTS = {
  "idea_generator_ai": {
    "id": "idea_generator_ai",
    "title": "Idea Generator AI",
    "purpose": "Produce a large batch of distinct, scoreable product ideas in one call.",
    "system": "You are Idea Generator AI. You produce BATCHES of distinct digital product ideas
for an Etsy-first studio, each one annotated with the raw market signals a
scoring engine will use. You are a generator, not a judge: never rank the ideas
and never drop one for being weak - the scoring engine decides that.

Rules:
- Every idea in the batch must be genuinely different. Two ideas that differ only
  by an adjective ("cute planner" / "lovely planner") count as one and are wasted.
- Spread ideas across the sub-niches, customer situations and use cases implied
  by the research, not just the obvious one.
- `title` is a working name, max 60 characters, plain English, no emoji.
- `factory` MUST be one of: planner, printable, canva, wallart, resume,
  spreadsheet, kids, svg.
- Scores are YOUR ESTIMATES on a 0-100 scale, grounded in the market signals:
  - `demand_score`      how many buyers actively search for this
  - `competition_score` how crowded it already is (HIGH = bad)
  - `trend_score`       momentum right now (seasonal spikes count)
  - `seo_score`         how winnable the keywords are for a new shop
- `est_price_usd` must sit inside the price range the research observed.
- `difficulty` is easy | medium | hard. `lifecycle` is evergreen | seasonal.
- Never reference a real brand, franchise, celebrity or licensed character.
- Output valid JSON only.",
    "user_template": "RESEARCH CONCEPT:
{{research_json}}

MARKET SIGNALS:
{{market_json}}

CATEGORIES THAT ARE UNDER-REPRESENTED IN THE SHOP (favour these):
{{wanted_categories}}

CATEGORIES THAT ARE ALREADY CROWDED (avoid unless the angle is genuinely new):
{{crowded_categories}}

TITLES THAT ALREADY EXIST (do not repeat or paraphrase these):
{{existing_titles}}

Generate exactly {{batch_size}} distinct ideas, batch id {{batch_id}}.
Answer with the exact JSON contract.",
    "output_contract": "{
  "ideas": [
    {
      "title": "string",
      "category": "string",
      "factory": "planner|printable|canva|wallart|resume|spreadsheet|kids|svg",
      "target_customer": "string",
      "keywords": ["string"],
      "demand_score": 0,
      "competition_score": 0,
      "trend_score": 0,
      "seo_score": 0,
      "est_price_usd": 0,
      "difficulty": "easy|medium|hard",
      "lifecycle": "evergreen|seasonal",
      "angle": "string"
    }
  ]
}"
  }
};

return $input.all().map((item) => ({
  json: { ...item.json, prompt_version: PROMPT_VERSION, prompts: PROMPTS },
}));

// Entry point. target_count is clamped to the 100-500 band the spec requires.
const ctx = $input.first().json;
const research = ctx.research || {};

if (!research.keyword) {
  throw new Error('07 Idea Factory requires a research package');
}

const requested = Number(ctx.idea_count || $('Factory Config').first().json.cfg.IDEA_TARGET_COUNT || 200);
const target = Math.max(100, Math.min(500, Math.round(requested)));
const batchSize = Math.max(10, Math.min(40, Number($('Factory Config').first().json.cfg.IDEA_BATCH_SIZE || 25)));

return [{
  json: {
    run_id: ctx.run_id,
    factory: ctx.factory,
    factory_locked: ctx.factory_locked === true,
    prompt_version: ctx.prompt_version || $('Factory Config').first().json.cfg.PROMPT_VERSION || 'v1.0.0',
    dry_run: ctx.dry_run === true,
    research,
    market: ctx.market || {},
    target_count: target,
    batch_size: batchSize,
    batch_count: Math.ceil(target / batchSize),
    started_at: new Date().toISOString(),
  },
}];

// Section 3 + 4: turn the inventory snapshot into saturation levels and the
// category shopping list the idea generator should aim at.
const ctx = $('Normalize Idea Input').first().json;
const row = $input.first().json || {};

const asArray = (value) => {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') { try { return JSON.parse(value); } catch (e) { return []; } }
  return value ? value : [];
};

const total = Number(row.total_products || 0);
const categories = asArray(row.categories);
const existing = asArray(row.existing);
const pending = asArray(row.pending_ideas);
const targets = asArray(row.targets);

const targetByCategory = new Map(targets.map((t) => [t.category, Number(t.target_pct)]));
const countByCategory = new Map(categories.map((c) => [c.category, Number(c.products)]));

// Actual vs target share, per category the shop cares about.
const balance = [];
const universe = new Set([...targetByCategory.keys(), ...countByCategory.keys()]);
for (const category of universe) {
  const count = countByCategory.get(category) || 0;
  const actualPct = total ? (count * 100) / total : 0;
  const targetPct = targetByCategory.has(category) ? targetByCategory.get(category) : 0;
  balance.push({
    category,
    products: count,
    actual_pct: Math.round(actualPct * 10) / 10,
    target_pct: targetPct,
    gap_pct: Math.round((targetPct - actualPct) * 10) / 10,
    // 0 = empty shelf, 1 = at target, >1 = overstocked
    saturation: targetPct > 0 ? actualPct / targetPct : (count ? 2 : 0),
  });
}
balance.sort((a, b) => b.gap_pct - a.gap_pct);

const wanted = balance.filter((b) => b.gap_pct > 2).map((b) => b.category);
const crowded = balance.filter((b) => b.saturation > 1.15).map((b) => b.category);

return [{
  json: {
    ...ctx,
    inventory: {
      total_products: total,
      balance,
      wanted_categories: wanted.length ? wanted : balance.slice(0, 3).map((b) => b.category),
      crowded_categories: crowded,
      existing_titles: existing.map((e) => e.title_norm).filter(Boolean),
      existing_records: existing,
      pending_titles: pending.map((p) => p.title_norm).filter(Boolean),
    },
  },
}];

// One item per generation batch. Batching keeps each completion inside a sane
// token budget and means a single bad batch does not lose the whole pool.
const ctx = $input.first().json;
const batches = [];
let remaining = ctx.target_count;

for (let i = 0; i < ctx.batch_count; i += 1) {
  const size = Math.min(ctx.batch_size, remaining);
  remaining -= size;
  batches.push({
    batch_index: i + 1,
    batch_id: `${ctx.run_id}-b${String(i + 1).padStart(2, '0')}`,
    batch_size: size,
    dry_run: ctx.dry_run,
  });
}

return batches.filter((b) => b.batch_size > 0).map((json) => ({ json }));

// Mustache-style renderer for the {{placeholders}} in the prompt templates.
const render = (template, vars) =>
  String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) =>
    vars[key] === undefined || vars[key] === null ? '' : String(vars[key]));

const ctx = $('Parse Inventory Snapshot').first().json;
const batch = $input.first().json;
const agent = $('Prompt Library').first().json.prompts.idea_generator_ai;

// Rotate the "avoid" list so later batches see the titles earlier batches made,
// which is what actually stops the model repeating itself across a 500-idea run.
let produced = [];
try {
  produced = $('Collect Raw Ideas').all().map((i) => i.json.title_norm);
} catch (e) {
  produced = [];
}

const avoid = [...ctx.inventory.existing_titles, ...ctx.inventory.pending_titles, ...produced]
  .slice(-180);

return [{
  json: {
    ...batch,
    idea_user_prompt: render(agent.user_template, {
      research_json: JSON.stringify(ctx.research, null, 2),
      market_json: JSON.stringify(ctx.market, null, 2),
      wanted_categories: ctx.inventory.wanted_categories.join(', ') || '(none - shop is balanced)',
      crowded_categories: ctx.inventory.crowded_categories.join(', ') || '(none)',
      existing_titles: avoid.join('\n') || '(none yet)',
      batch_size: batch.batch_size,
      batch_id: batch.batch_id,
    }),
  },
}];

